with parsed as (select id, coupon_codes, items, attributes, array_join(array_sort(coupon_codes), ',') as coupons_text, try_cast(attributes['weight_kg'] as double) as weight_kg, size(items) as num_items, exists(items, item -> item.price > 100) as has_premium_item, coalesce(attributes['gift'], 'none') as gift_or_default from carts) select *, lag(weight_kg, 2, 0) over w_grp prev_weight_kg, avg(num_items) over (order by num_items, id rows between 5 preceding and current row) num_items_avg_5, sum(num_items) over w_ordered running_num_items, ntile(5) over w_grp weight_kg_bucket, last_value(gift_or_default) ignore nulls over (order by num_items, id rows between unbounded preceding and current row) last_known_gift_or_default from parsed window w_grp as (order by weight_kg, id), w_ordered as (order by weight_kg, id rows between unbounded preceding and current row)
